Object.assign(I.en,{webAuth:'Web authentication',authNone:'None',authBasic:'HTTP Basic',authForm:'Configured form',loginPath:'Login path',usernameSelector:'Username selector',passwordSelector:'Password selector',submitSelector:'Submit selector',webToolsReady:'Four read-only MCP tools are available for publication: open, snapshot, wait and close.',sessionsIntro:'Currently active ephemeral Web sessions.',emptySessions:'No active Web session.',age:'Age',idle:'Idle'});
